package com.learnagent.analysis;import com.learnagent.quiz.*;import com.learnagent.task.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class AnalysisService{private final AnswerRecordRepository answers;private final QuizRepository quizzes;private final StudyTaskRepository tasks;private final AnalysisProperties props;public AnalysisService(AnswerRecordRepository a,QuizRepository q,StudyTaskRepository t,AnalysisProperties p){answers=a;quizzes=q;tasks=t;props=p;}public List<WeakPoint> weakPoints(UUID course){List<AnswerRecord> records=course==null?answers.findAll():answers.findByCourseId(course);Map<String,List<AnswerRecord>> groups=new HashMap<>();records.forEach(r->groups.computeIfAbsent(r.getKnowledgePoint(),x->new ArrayList<>()).add(r));return groups.entrySet().stream().map(e->point(e.getKey(),e.getValue())).filter(p->p.attemptCount()>=props.minimumAttempts()&&p.accuracy()<props.weakPointThreshold()).sorted(Comparator.comparingDouble(WeakPoint::accuracy)).toList();}public Statistics statistics(UUID course){List<AnswerRecord> r=course==null?answers.findAll():answers.findByCourseId(course);int correct=(int)r.stream().filter(AnswerRecord::isCorrect).count();long completed=tasks.countByStatus(TaskStatus.COMPLETED);long pending=tasks.countByStatus(TaskStatus.TODO)+tasks.countByStatus(TaskStatus.IN_PROGRESS);return new Statistics(course==null?quizzes.count():quizzes.findByCourseId(course).size(),r.size(),correct,r.isEmpty()?0:(double)correct/r.size(),completed,pending,weakPoints(course).size());}private WeakPoint point(String key,List<AnswerRecord> rs){int correct=(int)rs.stream().filter(AnswerRecord::isCorrect).count();return new WeakPoint(key,rs.size(),correct,rs.size()-correct,(double)correct/rs.size());}public record WeakPoint(String knowledgePoint,int attemptCount,int correctCount,int wrongCount,double accuracy){}public record Statistics(long totalQuizzes,long totalQuestionsAnswered,int correctAnswers,double overallAccuracy,long completedTasks,long pendingTasks,int weakPointCount){}}
